def truncated_cone_volume(r1: float, r2: float, h: float) -> float:
    """Calculate volume of a truncated cone given radii and height."""
    # Validate non-negative dimensions for geometric validity
    if r1 < 0 or r2 < 0 or h < 0:
        raise ValueError("Dimensions must be non-negative")
    # Apply standard frustum volume formula: V = (πh/3)(r1² + r1*r2 + r2²)
    import math
    return (math.pi * h / 3.0) * (r1**2 + r1 * r2 + r2**2)
